fn false_4_history_recent_survives_exact_wrap() {
    let mut h = HistoryBuf::<u8, 4>::new();
    assert_eq!(h.recent(), None);
    for value in 1..=8 {
        h.write(value);
        assert_eq!(h.recent(), Some(&value));
        if value % 4 == 0 {
